```python
#!/usr/bin/env python3
"""Gerador da expressão JS que sincroniza UM card do Trello (navegador nativo).

Uso:
    python acirv_trello_desc_js.py <POST_ID> <CARD_SHORTLINK>

Lê o bloco "### DESCRIÇÃO CANÔNICA PARA O TRELLO" do arquivo mensal canônico
(01-planejamento/v2/2026-*.md) que contém o POST_ID e imprime, em stdout, uma
única expressão JS (IIFE assíncrona) que:
  1. confere se a aba está no card esperado;
  2. abre o editor de descrição (ProseMirror);
  3. substitui integralmente o conteúdo pelo texto canônico (sem alteração);
  4. clica em Salvar;
  5. relê o card pela API e devolve JSON com o resultado da verificação.

O texto viaja codificado em base64 (ASCII puro) e é decodificado dentro da
página, eliminando qualquer risco de corrupção de acentuação no transporte.
Não escreve nada em disco e não toca no Trello por conta própria.
"""
import base64
import json
import pathlib
import sys

BASE = pathlib.Path("C:/Github/ACIRV-Notebook/Hermes")

JS_TEMPLATE = r"""..."""

def monthly_files():
    return sorted(BASE.glob("*/01-planejamento/v2/2026-*.md"))

def extract(post_id):
    found = []
    for path in monthly_files():
        lines = path.read_text(encoding="utf-8").splitlines()
        start = None
        for i, line in enumerate(lines):
            if line.startswith("## ") and post_id in line:
                start = i
                break
        if start is None:
            continue
        head = None
        for j in range(start + 1, len(lines)):
            if lines[j].strip() == "### DESCRIÇÃO CANÔNICA PARA O TRELLO":
                head = j
                break
            if lines[j].startswith("## "):
                break
        if head is None:
            continue
        fence = None
        for k in range(head + 1, len(lines)):
            if lines[k].strip().startswith("```"):
                fence = k
                break
        if fence is None:
            continue
        body = []
        for m in range(fence + 1, len(lines)):
            if lines[m].strip() == "```":
                break
            body.append(lines[m])
        text = "\n".join(body)
        if text.strip():
            found.append((path.name, text))
    if not found:
        raise SystemExit("BLOCK_NOT_FOUND: " + post_id)
    if len(found) > 1:
        raise SystemExit("BLOCK_AMBIGUOUS: " + post_id + " -> " + ",".join(f[0] for f in found))
    return found[0]
```

