```python
#!/usr/bin/env python3
"""Exporta artefatos .data de uma execucao de work_execute para um relatorio .txt legivel.

Uso: acirv_export_artifacts.py <task_dir|NEWEST> <out_txt> [max_chars_per_item]
"""
import json
import pathlib
import sys

ROOT = pathlib.Path("C:/Users/Kevyn Lucas/AppData/Local/hermes/workstation/artifacts")


def newest_task_dir():
    dirs = [p for p in ROOT.iterdir() if p.is_dir()]
    if not dirs:
        raise SystemExit("NENHUM_DIR")
    return max(dirs, key=lambda p: p.stat().st_mtime)


def main():
    which = sys.argv[1]
    out = pathlib.Path(sys.argv[2])
    cap = int(sys.argv[3]) if len(sys.argv) > 3 else 1200
    d = newest_task_dir() if which.upper() == "NEWEST" else pathlib.Path(which)
    rows = ["TASK " + str(d), "FILES " + str(len(list(d.glob("*.data"))))]
    for p in sorted(d.glob("*.data"), key=lambda x: x.stat().st_mtime):
        raw = p.read_bytes()
        head = raw[:cap]
        rows.append("--- " + p.name[:12] + " size=" + str(len(raw)))
        rows.append(head.decode("utf-8", errors="replace"))
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text("\n".join(rows), encoding="utf-8")
    print("EXPORT_OK", str(out), len(rows))


if __name__ == "__main__":
    main()
```

