SC = pathlib.Path(r'C:/Users/Kevyn Lucas/AppData/Local/hermes/scratch')
canon = json.loads((SC / 'acirv_canon.json').read_text(encoding='utf-8'))

MAP = [
    ('SUXu5o63', 'ACIRV-SM-2026-001'),
