    ('UvcwnAFK', 'ACIRV-SM-2026-006'),
    ('6PVVFLwt', 'ACIRV-SM-2026-007'),
    ('i4MUHERX', 'ACIRV-SM-2026-008'),
    ('01E2Oicn', 'ACIRV-SM-2026-047'),
    ('1B3pbnDG', 'ACIRV-SM-2026-009'),
]

# Monta UM script JS que faz todos os 12 via UI, e devolve o descLen lido do servidor.
# A fidelidade usa ClipboardEvent paste (nao insertText) -> \n\n = paragrafo, \n = <br>
DESCS = [{'id': tid, 'post': post, 'desc': canon[post]} for tid, post in MAP]

js = r'''
(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const ITEMS = __ITEMS__;
  const out = [];

  const apiGet = (id) => new Promise((res) => {
    const x = new XMLHttpRequest();
    x.open('GET', '/1/cards/' + id + '?fields=name,desc,due', false);
    x.send();
    try { res(JSON.parse(x.responseText)); } catch (e) { res(null); }
  });

  const setDescViaPaste = (ed, text) => {
    ed.focus();
    document.execCommand('selectAll');
    const dt = new DataTransfer();
    dt.setData('text/plain', text);
    ed.dispatchEvent(new ClipboardEvent('paste', {clipboardData: dt, bubbles: true, cancelable: true}));
  };

  for (const it of ITEMS) {
    const rec = {id: it.id, post: it.post, before: null, after: null, ok: false, err: null};
    try {
      const c0 = apiGet(it.id);
      rec.before = c0 ? (c0.desc || '').length : null;

      // abre o cartao pela URL (SPA navega sem recarregar)
      history.pushState({}, '', '/c/' + it.id);
      window.dispatchEvent(new PopStateEvent('popstate'));
      await sleep(2600);

      // botao Editar descricao
      let ed = document.querySelector('.ProseMirror[aria-label="Editar descrição"]');
      if (!ed) {
        const btn = document.querySelector('button[aria-label="Editar descrição"]')
                 || [...document.querySelectorAll('button')].find(b => /editar descri/i.test(b.getAttribute('aria-label') || ''));
        if (!btn) { rec.err = 'NO_EDIT_BUTTON'; out.push(rec); continue; }
        btn.click();
        await sleep(1200);
        ed = document.querySelector('.ProseMirror[aria-label="Editar descrição"]');
      }
      if (!ed) { rec.err = 'NO_EDITOR'; out.push(rec); continue; }

      setDescViaPaste(ed, it.desc);
      await sleep(900);

      const saveBtn = document.querySelector('[data-testid="description-save-button"]')
                   || [...document.querySelectorAll('button')].find(b => /^\s*salvar\s*$/i.test((b.innerText || '').trim()));
      if (!saveBtn) { rec.err = 'NO_SAVE_BUTTON'; out.push(rec); continue; }
      saveBtn.click();
      await sleep(2200);

      const c1 = apiGet(it.id);
      rec.after = c1 ? (c1.desc || '').length : null;
      rec.due = c1 ? c1.due : null;
      rec.ok = (rec.after === it.desc.length);
    } catch (e) {
      rec.err = String(e && e.message ? e.message : e);
    }
    out.push(rec);
  }
  return JSON.stringify(out);
})()
'''

js = js.replace('__ITEMS__', json.dumps(DESCS, ensure_ascii=False))
(SC / 'acirv_sync_all.js').write_text(js, encoding='utf-8')
print('JS written chars:', len(js))
print('items:', len(DESCS))
print('total desc chars:', sum(len(d['desc']) for d in DESCS))
