{"content": "(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const ID = 'SUXu5o63';
  const DESC = __DESC__;
  const apiGet = (id) => { const x = new XMLHttpRequest(); x.open('GET','/1/cards/'+id+'?fields=name,desc,due',false); x.send(); try { return JSON.parse(x.responseText); } catch(e){ return null; } };

  const rec = {id: ID, before: null, afterApi: null, domLen: null, due: null, err: null, saved: false};
  const c0 = apiGet(ID);
  rec.before = c0 ? (c0.desc||'').length : null;

  // 1) garante estar no cartao certo (SPA)
  if (!location.pathname.includes(ID)) {
    history.pushState({}, '', '/c/' + ID);
    window.dispatchEvent(new PopStateEvent('popstate'));
    await sleep(3000);
  }

  // 2) abre o editor
  let ed = document.querySelector('.ProseMirror');
  if (!ed) {
    const btn = [...document.querySelectorAll('button')].find(b => /editar\s+descri/i.test((b.getAttribute('aria-label')||'') + ' ' + (b.innerText||'')));
    if (!btn) { rec.err = 'NO_EDIT_BUTTON'; return JSON.stringify(rec); }
    btn.click();
    await sleep(1500);
    ed = document.querySelector('.ProseMirror');
  }
  if (!ed) { rec.err = 'NO_EDITOR'; return JSON.stringify(rec); }

  // 3) injeta com ClipboardEvent (preserva \n; ProseMirror: \n\n -> paragrafo, \n -> <br>)
  ed.focus();
  const sel = window.getSelection(); const rng = document.createRange();
  rng.selectNodeContents(ed); sel.removeAllRanges(); sel.addRange(rng);
  const dt = new DataTransfer();
  dt.setData('text/plain', DESC);
  ed.dispatchEvent(new ClipboardEvent('paste', {clipboardData: dt, bubbles: true, cancelable: true}));
  await sleep(1200);
  rec.domLen = ed.innerText.length;

  // 4) salvar
  const saveBtn = document.querySelector('[data-testid="description-save-button"]')
    || [...document.querySelectorAll('button')].find(b => /^\s*salvar(\s+altera[çc][õo]es)?\s*$/i.test((b.innerText||'').trim()));
  if (!saveBtn) { rec.err = 'NO_SAVE_BUTTON'; return JSON.stringify(rec); }
  saveBtn.click();
  await sleep(2500);

  // 5) readback independente (servidor)
  const c1 = apiGet(ID);
  rec.afterApi = c1 ? (c1.desc||'').length : null;
  rec.due = c1 ? c1.due : null;
  rec.saved = (rec.afterApi === DESC.length);
  rec.head = c1 ? (c1.desc||'').slice(0,50).replace(/\n/g,'|') : null;
  return JSON.stringify(rec);
})()
